CREATE TABLE `pose_data_scale` (\n  `id` bigint NOT NULL AUTO_INCREMENT,\n  `session_id` bigint NOT NULL,\n  `timestamp_sec` double NOT NULL,\n  `joint_coordinates` text CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL,\n  `sync_rate` double DEFAULT NULL,\n  `is_correct` tinyint(1) DEFAULT '1',\n  `feedback_message` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL,\n  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,\n  PRIMARY KEY (`id`,`created_at`),\n  KEY `idx_session_timestamp` (`session_id`,`timestamp_sec`)\n) ENGINE=InnoDB AUTO_INCREMENT=10485856 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
